{"command": "python3 - <<'PY'
import workcell, time

def locate(name):
    r=workcell.call('robot','locate',name)
    print('locate', name, r.ok, r.data)
    if not r.ok:
        raise RuntimeError(r.text)
    return r.data

for n in range(2,7):
    m=locate(f'M{n}')
    kname=f'K{n}'
    r=workcell.call('robot','pick',kname)
    print('pick', kname, r.ok, r.text, r.data)
    if not r.ok: raise RuntimeError(r.text)
    x=m['x']; y=m['y']
    r=workcell.call('robot','place',str(x),str(y))
    print('place', kname, x, y, r.ok, r.text, r.data)
    if not r.ok: raise RuntimeError(r.text)
    locate(kname)
PY"}

